import React, {useMemo} from 'react';
const Row = React.memo(({item}) => <Text>{item.name}</Text>);
export default function StopsList({stops, query}) {
  const filtered = useMemo(() => stops.filter(s => s.name.includes(query)), [stops, query]);
  return <FlatList data={filtered} renderItem={({item}) => <Row item={item} />} keyExtractor={s => s.id} getItemLayout={(d, i) => ({length: 40, offset: 40*i, index: i})} />;
